import sys

def main():
    e, n, w, s = map(int, sys.stdin.read().split())
    dx, dy = e - w, n - s
    parts = []
    if dy > 0:
        parts.append('North')
    elif dy < 0:
        parts.append('South')
    if dx > 0:
        parts.append('East')
    elif dx < 0:
        parts.append('West')
    print('-'.join(parts) if parts else 'Origin')

