def gen(rng):
    tests = []
    # all nine sign combinations
    for sx in (-1, 0, 1):
        for sy in (-1, 0, 1):
            e = rng.randint(0, 5)
            w = e
            if sx > 0:
                e += rng.randint(1, 5)
            if sx < 0:
                w += rng.randint(1, 5)
            n = rng.randint(0, 5)
            s = n
            if sy > 0:
                n += rng.randint(1, 5)
            if sy < 0:
                s += rng.randint(1, 5)
            tests.append(f'{e} {n} {w} {s}')
    tests += ['0 0 0 0', '1000000000 1000000000 1000000000 1000000000', '1000000000 0 0 1000000000',
              '0 1000000000 1000000000 0', '1000000000 1000000000 0 0', '0 0 1000000000 1000000000',
              '1000000000 999999999 999999999 1000000000']
    for _ in range(6):
        tests.append(' '.join(str(rng.randint(0, 10**9)) for _ in range(4)))
    for _ in range(6):
        tests.append(' '.join(str(rng.randint(0, 3)) for _ in range(4)))
    return tests

